-- UNI-OPS-01 Option C / U1B existing-source review membrane (HELD).
-- A root can inspect individually preserved native Rule labels and eligible
-- class/Subject choices. No new interview, interpretation, bulk approval,
-- Subject-wide disclosure or Work generated by this read.
CREATE FUNCTION atlas.list_governed_native_farm_rule_sources_owner_self_api_v1(
 p_organization_id uuid,p_ledger_id uuid,p_farm_id uuid,
 p_limit integer DEFAULT 20,p_after_rule_id uuid DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO ''
AS $list$
DECLARE v_actor uuid;v_principal uuid;
 v_items jsonb;v_more boolean;v_next uuid;
BEGIN
 v_principal:=atlas.foundry_current_signed_principal_v1();
 v_actor:=atlas.company_work_native_ledger_owner_self_v1(
  p_organization_id,p_ledger_id);
 IF v_actor IS NULL OR v_principal IS NULL
   OR v_principal IS DISTINCT FROM atlas.current_principal_id_v1()
   OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 25
   OR NOT EXISTS(SELECT 1 FROM atlas.farms f
      JOIN atlas.farm_crop_ledger_custody_v1 c ON c.farm_id=f.id
       AND c.ledger_id=p_ledger_id AND c.custody_state='active'
       AND c.ended_at IS NULL
      WHERE f.id=p_farm_id AND f.organization_id=p_organization_id
       AND f.status='active')
   OR NOT EXISTS(SELECT 1 FROM atlas.ledger_organization_participations l
      WHERE l.organization_id=p_organization_id AND l.ledger_id=p_ledger_id
       AND l.status='active' AND l.ended_at IS NULL
       AND l.participation_kind='governing' AND l.is_compatibility_primary=true)
 THEN RAISE EXCEPTION 'Exact current governing farm root required'
   USING ERRCODE='42501'; END IF;
 WITH source_rows AS (
  SELECT r.id,r.label,r.validity_interval_seconds
  FROM atlas.rhythm_rules r
  JOIN atlas.rhythm_bindings b ON b.rhythm_rule_id=r.id
    AND b.organization_id=p_organization_id AND b.farm_id=p_farm_id
    AND b.active
  WHERE r.status='active' AND r.validity_interval_seconds>0
    AND (p_after_rule_id IS NULL OR r.id>p_after_rule_id)
  GROUP BY r.id,r.label,r.validity_interval_seconds
  ORDER BY r.id LIMIT p_limit+1
 ), ranked AS (
  SELECT s.*,row_number() OVER(ORDER BY s.id) AS position
  FROM source_rows s
 )
 SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
   'sourceRuleId',r.id,'sourceRuleLabel',r.label,
   'sourceCadenceSeconds',r.validity_interval_seconds,
   'sourceKind','legacy_native_rhythm_rule',
   'preexistingSourceVerified',true,
   'classChoices',(
     SELECT coalesce(pg_catalog.jsonb_agg(c.object_type),'[]'::jsonb)
     FROM (
       SELECT DISTINCT g.object_type FROM atlas.rhythm_state s
       JOIN atlas.growing_objects g ON g.id=s.subject_id AND g.farm_id=s.farm_id
       WHERE s.organization_id=p_organization_id AND s.farm_id=p_farm_id
         AND s.rhythm_rule_id=r.id
       ORDER BY g.object_type LIMIT 24
     ) c
   ),
   'bulkApprovalPermitted',false
  ) ORDER BY r.id) FILTER(WHERE r.position<=p_limit),'[]'::jsonb),
  coalesce(bool_or(r.position>p_limit),false),
  (max(r.id::text) FILTER(WHERE r.position<=p_limit))::uuid
 INTO v_items,v_more,v_next FROM ranked r;
 RETURN pg_catalog.jsonb_build_object(
  'ok',true,'contractVersion','governed_native_farm_rule_choices_v1',
  'organizationId',p_organization_id,'ledgerId',p_ledger_id,
  'farmId',p_farm_id,'items',v_items,'hasMore',v_more,
  'nextAfterRuleId',CASE WHEN v_more THEN v_next ELSE NULL END,
  'sourceOnly',true,'notACompleteGovernedRulebook',true);
END;
$list$;
REVOKE ALL ON FUNCTION atlas.list_governed_native_farm_rule_sources_owner_self_api_v1(
 uuid,uuid,uuid,integer,uuid)
 FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION atlas.list_governed_native_farm_rule_subject_choices_owner_self_api_v1(
 p_organization_id uuid,p_ledger_id uuid,p_farm_id uuid,
 p_source_rule_id uuid,p_limit integer DEFAULT 20,
 p_after_subject_id uuid DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO ''
AS $subjects$
DECLARE v_root record;v_items jsonb;v_more boolean;v_next uuid;
BEGIN
 SELECT * INTO v_root FROM atlas.require_governed_farm_rulebook_root_v1(
  p_organization_id,p_ledger_id,p_farm_id,p_source_rule_id);
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 25 THEN
  RAISE EXCEPTION 'Bounded exact Subject review required'
   USING ERRCODE='22023';
 END IF;
 WITH subject_rows AS (
  SELECT g.id,g.label,g.object_type
  FROM atlas.rhythm_state s
  JOIN atlas.growing_objects g ON g.id=s.subject_id AND g.farm_id=s.farm_id
  JOIN reality.entities e ON e.id=g.id AND e.identity_state='canonical'
    AND e.entity_kind='growing_object'
    AND e.metadata->>'subjectDomain'='spatial'
  WHERE s.organization_id=p_organization_id AND s.farm_id=p_farm_id
    AND s.rhythm_rule_id=p_source_rule_id
    AND (p_after_subject_id IS NULL OR g.id>p_after_subject_id)
    AND coalesce(atlas.has_current_subject_disclosure_v1(
     p_ledger_id,v_root.actor_person_id,
     'spatial','growing_object',g.id,'identity'),false)
    AND coalesce(atlas.has_current_subject_disclosure_v1(
     p_ledger_id,v_root.actor_person_id,
     'spatial','growing_object',g.id,'condition'),false)
  GROUP BY g.id,g.label,g.object_type
  ORDER BY g.id LIMIT p_limit+1
 ), ranked AS (
  SELECT s.*,row_number() OVER(ORDER BY s.id) AS position
  FROM subject_rows s
 )
 SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
   'subjectId',r.id,'subjectLabel',r.label,'classKey',r.object_type,
   'canonicalSourceVerified',true
  ) ORDER BY r.id) FILTER(WHERE r.position<=p_limit),'[]'::jsonb),
  coalesce(bool_or(r.position>p_limit),false),
  (max(r.id::text) FILTER(WHERE r.position<=p_limit))::uuid
 INTO v_items,v_more,v_next FROM ranked r;
 RETURN pg_catalog.jsonb_build_object(
  'ok',true,'contractVersion','governed_native_farm_rule_subject_choices_v1',
  'organizationId',p_organization_id,'ledgerId',p_ledger_id,
  'farmId',p_farm_id,'sourceRuleId',p_source_rule_id,
  'items',v_items,'hasMore',v_more,
  'nextAfterSubjectId',CASE WHEN v_more THEN v_next ELSE NULL END,
  'notAllSubjectsVisible',true,'sourceOnly',true);
END;
$subjects$;
REVOKE ALL ON FUNCTION atlas.list_governed_native_farm_rule_subject_choices_owner_self_api_v1(
 uuid,uuid,uuid,uuid,integer,uuid)
 FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.list_governed_native_farm_rule_sources_owner_self_api_v1(
 p_organization_id uuid,p_ledger_id uuid,p_farm_id uuid,
 p_limit integer DEFAULT 20,p_after_rule_id uuid DEFAULT NULL
) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO ''
AS $transport$
 SELECT atlas.list_governed_native_farm_rule_sources_owner_self_api_v1(
 p_organization_id,p_ledger_id,p_farm_id,p_limit,p_after_rule_id);
$transport$;
REVOKE ALL ON FUNCTION public.list_governed_native_farm_rule_sources_owner_self_api_v1(
 uuid,uuid,uuid,integer,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.list_governed_native_farm_rule_sources_owner_self_api_v1(
